static Arena *test_ir_result_arena(void) {
  static Arena *arena = NULL;
  if (arena == NULL) arena = arena_create(4096U);
  return arena;
}

typedef int (*TestSourceAnalysisMutator)(M68kSourceAnalysisIR *source_analysis, void *user_data);

static int test_render_ir_preview_build_with_source_analysis_mutator(const M68kObject *object,
    const M68kDecodeIR *decode,
    const M68kFactIR *facts, const M68kAnalysisPolicy *policy, uint8_t **accepted_start,
    uint8_t **accepted_bytes, const M68kAnalysisLabelPoint *analysis_labels, size_t analysis_label_count,
    int render_text_preview, int render_asm_source,
    int collect_asm_source_text, int emit_asm_source_text, M68kRenderIRPreview *out_preview,
    TestSourceAnalysisMutator source_analysis_mutator, void *source_analysis_mutator_data) {
  M68kRenderLookup lookup;
  M68kAnalysisPolicy default_policy;
  M68kSourceAnalysisIR source_analysis;
  M68kSourceAnalysisBuildStats source_analysis_stats;
  M68kPlatformAnalysisPassStats platform_analysis_stats;
  const M68kAnalysisPolicy *effective_policy = policy;
  int result = -1;
  int default_policy_live = 0;
  int source_analysis_live = 0;
  if (object == NULL || decode == NULL || facts == NULL || accepted_start == NULL || accepted_bytes == NULL ||
      out_preview == NULL) {
    return -1;
  }
  memset(&lookup, 0, sizeof(lookup));
  memset(&default_policy, 0, sizeof(default_policy));
  memset(&source_analysis, 0, sizeof(source_analysis));
  memset(&source_analysis_stats, 0, sizeof(source_analysis_stats));
  memset(&platform_analysis_stats, 0, sizeof(platform_analysis_stats));
  m68k_render_ir_preview_init(out_preview);
  out_preview->platform_backend_kind = object->platform_backend_kind;
  if (effective_policy == NULL) {
    m68k_analysis_policy_init_default(&default_policy);
    effective_policy = &default_policy;
    default_policy_live = 1;
  }
  if (m68k_render_lookup_build(&lookup, object, decode, facts, effective_policy, accepted_start,
      analysis_labels, analysis_label_count) != 0) goto cleanup;
  if (render_asm_source &&
      m68k_analysis_render_lookup_run_platform_passes(&lookup, decode, accepted_start, accepted_bytes,
        &platform_analysis_stats) != 0) {
    goto cleanup;
  }
  m68k_render_lookup_materialize_structured_long_table_target_labels(&lookup, decode);
  m68k_render_lookup_materialize_relocation_target_labels(&lookup);
  if (render_asm_source) {
    if (m68k_ir_source_analysis_create(&source_analysis) != 0) goto cleanup;
    source_analysis_live = 1;
    source_analysis.file_kind = object->platform_file_kind;
    if (m68k_ir_source_analysis_set_policy(&source_analysis, effective_policy) != 0) goto cleanup;
    if (m68k_analysis_render_lookup_build_source_analysis(&lookup, decode, effective_policy,
        accepted_start, accepted_bytes, &source_analysis, &source_analysis_stats) != 0) {
      goto cleanup;
    }
    if (m68k_source_quality_analyze(&source_analysis, decode, facts, accepted_start, accepted_bytes) != 0)
      goto cleanup;
    if (source_analysis_mutator != NULL &&
        source_analysis_mutator(&source_analysis, source_analysis_mutator_data) != 0) {
      goto cleanup;
    }
  }
  result = m68k_render_ir_preview_emit_prepared(object, decode, &lookup, effective_policy, accepted_start, accepted_bytes,
    render_text_preview, render_asm_source, collect_asm_source_text, emit_asm_source_text, out_preview,
    render_asm_source ? &source_analysis : NULL);
cleanup:
  if (source_analysis_live) m68k_ir_source_analysis_destroy(&source_analysis);
  if (default_policy_live) m68k_analysis_policy_destroy(&default_policy);
  m68k_render_lookup_destroy(&lookup);
  return result;
}

static int test_render_ir_preview_build(const M68kObject *object, const M68kDecodeIR *decode,
    const M68kFactIR *facts, const M68kAnalysisPolicy *policy, uint8_t **accepted_start,
    uint8_t **accepted_bytes, const M68kAnalysisLabelPoint *analysis_labels, size_t analysis_label_count,
    int render_text_preview, int render_asm_source,
    int collect_asm_source_text, int emit_asm_source_text, M68kRenderIRPreview *out_preview) {
  return test_render_ir_preview_build_with_source_analysis_mutator(object, decode, facts, policy, accepted_start,
    accepted_bytes, analysis_labels, analysis_label_count, render_text_preview, render_asm_source,
    collect_asm_source_text, emit_asm_source_text, out_preview, NULL, NULL);
}

static int test_clear_platform_semantic_uses_and_expected_accesses(M68kSourceAnalysisIR *source_analysis,
    void *user_data) {
  size_t section_index;
  (void)user_data;
  if (source_analysis == NULL) return -1;
  for (section_index = 0U; section_index < source_analysis->section_count; ++section_index) {
    source_analysis->sections[section_index].platform_semantic_use_count = 0U;
    source_analysis->sections[section_index].expected_symbol_access_count = 0U;
  }
  return 0;
}

