static int test_facts_v2_source_analysis_records_disk_entry_loader_media_transfer(void) {
  M68kObject object;
  M68kSection section;
  M68kObjectAddResult added;
  M68kAnalysisPolicy policy;
  M68kFactsV2Profile profile;
  M68kSourceAnalysisIR source_analysis;
  char *source = NULL;
  uint8_t bytes[] = {
    0x41u, 0xfau, 0x00u, 0x0cu,             /* lea.l path(pc),a0 */
    0x43u, 0xf9u, 0x00u, 0x00u, 0x20u, 0x00u, /* lea.l $2000.l,a1 */
    0x4eu, 0x43u,                           /* trap #3 */
    0x4eu, 0x75u,                           /* rts */
    0x41u, 0x53u, 0x53u, 0x45u, 0x54u, 0x00u
  };
  memset(&section, 0, sizeof(section));
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  object.platform_backend_kind = M68K_PLATFORM_BACKEND_AMIGA_HUNK;
  object.platform_file_kind = M68K_PLATFORM_FILE_EXECUTABLE;
  section.kind = M68K_SECTION_CODE;
  section.data = bytes;
  section.size = sizeof(bytes);
  section.data_size = sizeof(bytes);
  added = m68k_object_add_section(&object, &section);
  M68K_C_ASSERT(added.ok);
  m68k_analysis_policy_init_default(&policy);
  strcpy(policy.source_context_kind, "disk_entry");
  strcpy(policy.source_context_disk_path, "disk.adf");
  strcpy(policy.source_context_entry_path, "LOADER");
  memset(&source_analysis, 0, sizeof(source_analysis));
  M68K_C_ASSERT_INT(0, m68k_facts_v2_render_asm_source_analysis_profile_alloc(&object, &policy, &source,
    &profile, &source_analysis, 1U, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(source != NULL);
  M68K_C_ASSERT_U32(1U, (uint32_t)source_analysis.section_count);
  M68K_C_ASSERT_U32(1U,
    (uint32_t)source_analysis.sections[0].recovered_platform_media_transfer_count);
  M68K_C_ASSERT_U32(10U, source_analysis.sections[0].recovered_platform_media_transfers[0].offset);
  M68K_C_ASSERT_U32(14U, source_analysis.sections[0].recovered_platform_media_transfers[0].path_offset);
  M68K_C_ASSERT_U32(0x2000U,
    source_analysis.sections[0].recovered_platform_media_transfers[0].destination_addr);
  M68K_C_ASSERT_U32(0U, source_analysis.sections[0].recovered_platform_media_transfers[0].source_size);
  M68K_C_ASSERT_STR("ASSET", source_analysis.sections[0].recovered_platform_media_transfers[0].path);
  M68K_C_ASSERT_U32(M68K_RECOVERED_PLATFORM_TRANSFER_SOURCE_TARGET_LOADER_FILE,
    source_analysis.sections[0].recovered_platform_media_transfers[0].source_kind);
  m68k_ir_source_analysis_destroy(&source_analysis);
  m68k_facts_v2_free_text(source);
  m68k_object_destroy(&object);
  return 0;
}

static int test_section_append_statement_copies_data(void) {
  M68kSectionIR section;
  M68kStatementIR statement;
  uint8_t bytes[2] = {0x12u, 0x34u};

  M68K_C_ASSERT_INT(0, m68k_ir_section_create(&section, test_ir_result_arena()));
  m68k_ir_statement_init(&statement);
  statement.kind = M68K_STATEMENT_DATA;
  statement.comment_kind = M68K_STATEMENT_COMMENT_METADATA;
  statement.label_name = "lbl";
  statement.comment = "comment";
  statement.u.data.kind = M68K_DATA_ITEM_BYTES;
  statement.u.data.data = bytes;
  statement.u.data.size = sizeof(bytes);
  statement.u.data.expr_text = "expr";

  M68K_C_ASSERT_INT(0, m68k_ir_section_append_statement(&section, &statement));
  M68K_C_ASSERT_INT(1, (int)section.statement_count);
  M68K_C_ASSERT(section.statements[0].label_name != statement.label_name);
  M68K_C_ASSERT(section.statements[0].comment != statement.comment);
  M68K_C_ASSERT(section.statements[0].u.data.data != statement.u.data.data);
  M68K_C_ASSERT(section.statements[0].u.data.expr_text != statement.u.data.expr_text);
  M68K_C_ASSERT_U32(M68K_STATEMENT_COMMENT_METADATA, section.statements[0].comment_kind);
  M68K_C_ASSERT_STR("lbl", section.statements[0].label_name);
  M68K_C_ASSERT_STR("comment", section.statements[0].comment);
  M68K_C_ASSERT_STR("expr", section.statements[0].u.data.expr_text);
  M68K_C_ASSERT_U32(0x12u, section.statements[0].u.data.data[0]);
  M68K_C_ASSERT_U32(0x34u, section.statements[0].u.data.data[1]);

  m68k_ir_section_destroy(&section);
  return 0;
}

