    "SECTION section_0,code\n"
    "start:\n"
    "\tmove.w d1,-(a7)\n"
    "\tlea.l table(pc,d1.w),a0\n"
    "\tmove.w (a7)+,d1\n"
    "\tmove.b (a0)+,(a3)+\n"
    "\tmove.b (a0)+,(a3)+\n"
    "\tmove.b (a0)+,(a3)+\n"
    "\tbra.s after\n"
    "table:\n"
    "\tdc.b $30,$31,$32,$33,$34,$35\n"
    "after:\n"
    "\trts\n";
  M68K_C_ASSERT_INT(0, m68k_source_model_create(&parsed_source));
