  uint8_t code_bytes[8] = {0x4eu, 0x71u, 0x4eu, 0x75u, 0x00u, 0x00u, 0x00u, 0x0au};
  uint8_t data_bytes[8] = {0};
  memset(&code_section, 0, sizeof(code_section));
  memset(&data_section, 0, sizeof(data_section));
  memset(&fixup, 0, sizeof(fixup));
