static int test_facts_v2_render_asm_source_renders_symbolic_branch(void) {
  M68kObject object;
  M68kSection section;
  M68kObjectAddResult added;
  M68kAnalysisPolicy policy;
  M68kFactsV2Profile profile;
  M68kRenderPlan source_plan;
  M68kRenderPlan listing_plan;
  M68kSourceAnalysisIR *source_analysis = NULL;
  M68kSourceAnalysisIR *listing_analysis = NULL;
  M68kRenderEvidenceIR source_evidence;
  M68kRenderEvidenceIR listing_evidence;
  char *source = NULL;
  char *plan_source = NULL;
  char *listing_analysis_json = NULL;
  M68kFactsV2Profile listing_profile;
  size_t row_index;
    int saw_section_row = 0;
    int saw_label_row = 0;
    int saw_instruction_source_row = 0;
    int saw_expected_target_label_access = 0;
    int saw_rendered_target_label_access = 0;
    int saw_expected_branch_target_access = 0;
    int saw_rendered_branch_target_access = 0;
  uint8_t bytes[6] = {0x60u, 0x02u, 0x4eu, 0x71u, 0x4eu, 0x75u};
  memset(&section, 0, sizeof(section));
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  section.kind = M68K_SECTION_CODE;
  section.size = sizeof(bytes);
  section.data_size = sizeof(bytes);
  section.data = bytes;
  added = m68k_object_add_section(&object, &section);
  M68K_C_ASSERT(added.ok);
  source_analysis = (M68kSourceAnalysisIR *)calloc(1U, sizeof(*source_analysis));
  listing_analysis = (M68kSourceAnalysisIR *)calloc(1U, sizeof(*listing_analysis));
  M68K_C_ASSERT(source_analysis != NULL && listing_analysis != NULL);
  m68k_analysis_policy_init_default(&policy);
  M68K_C_ASSERT_INT(0, m68k_facts_v2_render_asm_source_plan_analysis_profile_evidence_alloc(&object, &policy, &source,
    &source_plan, &profile, source_analysis, &source_evidence, 1U, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(source != NULL);
  M68K_C_ASSERT_INT(0, m68k_render_plan_emit_all_alloc(&source_plan, &plan_source));
  M68K_C_ASSERT_STR(source, plan_source);
  M68K_C_ASSERT(strstr(source, "    SECTION section,code") != NULL);
  M68K_C_ASSERT(strstr(source, "loc_0_00000004:") != NULL);
  M68K_C_ASSERT_U32(M68K_ASM_MNEMONIC_FAMILY_BRANCH,
    g_m68k_asm_mnemonic_metadata[M68K_ASM_MNEMONIC_BRA].family);
  M68K_C_ASSERT(strstr(source, "\tbra.b loc_0_00000004\n") != NULL);
  M68K_C_ASSERT(strstr(source, "loc_0_00000004") != NULL);
  M68K_C_ASSERT(strstr(source, "facts_v2 instruction bytes") == NULL);
  for (row_index = 0U; row_index < source_plan.row_count; ++row_index) {
    const M68kRenderPlanRow *row = &source_plan.rows[row_index];
    M68K_C_ASSERT_U32(0U, row->kind == M68K_RENDER_PLAN_ROW_DIAGNOSTIC ? 1U : 0U);
    if (row->kind == M68K_RENDER_PLAN_ROW_SECTION) saw_section_row = 1;
    if (row->kind == M68K_RENDER_PLAN_ROW_LABEL && row->has_source_range) saw_label_row = 1;
    if (row->kind == M68K_RENDER_PLAN_ROW_INSTRUCTION && row->has_source_range &&
        row->source_offset == 0U && row->source_size == 2U)
      saw_instruction_source_row = 1;
  }
  M68K_C_ASSERT(saw_section_row);
  M68K_C_ASSERT(saw_label_row);
  M68K_C_ASSERT(saw_instruction_source_row);
  M68K_C_ASSERT_U32(profile.asm_source_lines, profile.asm_source_plan_rows);
  M68K_C_ASSERT_U32(profile.asm_source_lines, profile.asm_source_plan_lines);
  M68K_C_ASSERT_U32(profile.asm_source_bytes, profile.asm_source_plan_bytes);
    M68K_C_ASSERT_U32(2U, profile.asm_source_symbolic_instructions);
    M68K_C_ASSERT_U32(0U, profile.asm_source_instruction_render_failures);
    M68K_C_ASSERT_U32(0U, profile.asm_source_instruction_byte_mismatches);
    M68K_C_ASSERT_U32(0U, profile.asm_source_instruction_relocation_failures);
    if (source_analysis->section_count > 0U) {
      size_t access_index;
      const M68kSectionAnalysisIR *analysis_section = &source_analysis->sections[0];
      for (access_index = 0U; access_index < analysis_section->expected_symbol_access_count; ++access_index) {
        const M68kExpectedSymbolAccessIR *access = &analysis_section->expected_symbol_accesses[access_index];
        if (access->offset == 4U &&
            access->target_section_index == 0U &&
            access->target_offset == 4U &&
            access->access_kind == M68K_EXPECTED_SYMBOL_ACCESS_LABEL_STATEMENT &&
            access->symbol_name != NULL &&
            strcmp(access->symbol_name, "loc_0_00000004") == 0) {
          saw_expected_target_label_access = 1;
        }
        if (access->offset == 0U &&
            access->target_section_index == 0U &&
            access->target_offset == 4U &&
            access->access_kind == M68K_EXPECTED_SYMBOL_ACCESS_BRANCH_TARGET &&
            access->symbol_name != NULL &&
            strcmp(access->symbol_name, "loc_0_00000004") == 0) {
          saw_expected_branch_target_access = 1;
        }
      }
    }
    saw_rendered_target_label_access = test_render_evidence_has_symbol_access(&source_evidence, 0U, 4U, UINT32_MAX,
      M68K_RENDERED_SYMBOL_ACCESS_LABEL_STATEMENT, "loc_0_00000004", 0U, 4U);
    saw_rendered_branch_target_access = test_render_evidence_has_symbol_access(&source_evidence, 0U, 0U, 0U,
      M68K_RENDERED_SYMBOL_ACCESS_BRANCH_TARGET, "loc_0_00000004", 0U, 4U);
    M68K_C_ASSERT(saw_expected_branch_target_access);
    M68K_C_ASSERT(saw_expected_target_label_access);
    M68K_C_ASSERT(saw_rendered_target_label_access);
    M68K_C_ASSERT(saw_rendered_branch_target_access);
    M68K_C_ASSERT_INT(0, m68k_facts_v2_render_asm_source_plan_analysis_profile_evidence_alloc(&object, &policy,
      NULL, &listing_plan, &listing_profile, listing_analysis, &listing_evidence, 1U, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(listing_plan.row_count != 0U);
  M68K_C_ASSERT(listing_evidence.section_count != 0U);
  M68K_C_ASSERT_INT(0, source_analysis_to_json_with_render_evidence(listing_analysis, &listing_evidence,
    &listing_analysis_json, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(listing_analysis_json != NULL);
  M68K_C_ASSERT(strstr(listing_analysis_json, "\"rendered_symbol_access_count\":") != NULL);
  M68K_C_ASSERT(strstr(listing_analysis_json, "\"access_kind\":\"branch_target\"") != NULL);
  M68K_C_ASSERT_U32(listing_profile.asm_source_bytes, listing_profile.asm_source_plan_bytes);
  M68K_C_ASSERT_U32(listing_profile.asm_source_lines, listing_profile.asm_source_plan_lines);
  free(listing_analysis_json);
  m68k_ir_render_evidence_destroy(&listing_evidence);
  m68k_render_plan_destroy(&listing_plan);
  m68k_ir_source_analysis_destroy(listing_analysis);
  free(listing_analysis);
  m68k_render_plan_free_text(plan_source);
  m68k_ir_render_evidence_destroy(&source_evidence);
  m68k_render_plan_destroy(&source_plan);
  m68k_ir_source_analysis_destroy(source_analysis);
  free(source_analysis);
  m68k_facts_v2_free_text(source);
  m68k_object_destroy(&object);
  return 0;
}

