  bytes[0x111] = 0xBBu;
  bytes[0x112] = 0xCCu;
  bytes[0x113] = 0xDDu;
  bytes[0x114] = 0x11u;
  bytes[0x115] = 0x22u;
  bytes[0x116] = 0x33u;
  bytes[0x117] = 0x44u;
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  object.platform_backend_kind = M68K_PLATFORM_BACKEND_AMIGA_HUNK;
  section.kind = M68K_SECTION_CODE;
