    "SECTION section_0,code\n"
    "\tlea copied(pc),a0\n"
    "\tlea $00000100.l,a1\n"
    "\tmovea.l a1,a2\n"
    "\tmoveq #7,d0\n"
    "copy:\n"
    "\tmove.b (a0)+,(a1)+\n"
    "\tdbf d0,copy\n"
    "\tjmp $0004(a2)\n"
    "\trts\n"
    "copied:\n"
    "\tnop\n"
    "\tnop\n"
    "entry:\n"
    "\tnop\n"
    "\trts\n";
  M68K_C_ASSERT_INT(0, m68k_source_model_create(&parsed_source));
  memset(&object, 0, sizeof(object));
  memset(&source_analysis, 0, sizeof(source_analysis));
