  M68K_C_ASSERT_U32(2U, ref->offset);
  M68K_C_ASSERT_U32(0x10U, ref->address);
  M68K_C_ASSERT_U32(M68K_ABSOLUTE_MEMORY_OWNER_CPU_VECTOR, ref->owner_kind);
  M68K_C_ASSERT_U32(M68K_SIM_ACCESS_MEMORY_WRITE, ref->access_kind);
