  bytes[0x10] = 0x4eu;
  bytes[0x11] = 0xd1u;
  bytes[0x22] = 0x10u;
  bytes[0x23] = 0x02u;
  bytes[0x28] = 0x01u;
  bytes[0x29] = 0x00u;
  bytes[0x40] = 0x70u;
  bytes[0x41] = 0x01u;
  bytes[0x42] = 0x4eu;
  bytes[0x43] = 0x75u;
  bytes[0x1042] = 0x70u;
  bytes[0x1043] = 0x02u;
  bytes[0x1044] = 0x4eu;
  bytes[0x1045] = 0x75u;
  memset(&section, 0, sizeof(section));
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
