static int test_facts_v2_pc_word_dispatch_descriptor_promotes_targets_beyond_inline_set(void) {
  enum {
    ENTRY_COUNT = 65,
    TABLE_OFFSET = 0x20,
    TARGET_START = TABLE_OFFSET + (ENTRY_COUNT * 2),
    TOTAL_SIZE = TARGET_START + (ENTRY_COUNT * 4)
  };
  M68kObject object;
  M68kSection section;
  M68kObjectAddResult added;
  M68kAnalysisPolicy policy;
  M68kFactsV2Profile profile;
  M68kSourceAnalysisIR source_analysis;
  char *source = NULL;
  const M68kTableConsumerIR *table_consumer = NULL;
  uint32_t late_target = TARGET_START + (64U * 4U);
  uint32_t saw_late_target = 0U;
  size_t code_start_index;
  size_t table_consumer_index;
  uint32_t index;
  uint8_t bytes[TOTAL_SIZE];
  memset(bytes, 0, sizeof(bytes));
  bytes[0x00] = 0x41U;
  bytes[0x01] = 0xF9U;
  test_store_u32be(bytes, 0x02U, TARGET_START);
  bytes[0x06] = 0xD0U;
  bytes[0x07] = 0xFBU;
  bytes[0x08] = 0x10U;
  bytes[0x09] = 0x18U;
  bytes[0x0A] = 0x4EU;
  bytes[0x0B] = 0xD0U;
  for (index = 0U; index < ENTRY_COUNT; ++index) {
    uint32_t target = TARGET_START + (index * 4U);
    test_store_u16be(bytes, TABLE_OFFSET + (index * 2U), (uint16_t)(target - TARGET_START));
    bytes[target] = 0x70U;
    bytes[target + 1U] = (uint8_t)index;
    bytes[target + 2U] = 0x4EU;
    bytes[target + 3U] = 0x75U;
  }
  memset(&section, 0, sizeof(section));
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  section.kind = M68K_SECTION_CODE;
  section.size = sizeof(bytes);
  section.data_size = sizeof(bytes);
  section.data = bytes;
  added = m68k_object_add_section(&object, &section);
  M68K_C_ASSERT(added.ok);
  m68k_analysis_policy_init_default(&policy);
  policy.entry_point_count = 1U;
  policy.entry_points[0].has_section_index = 1U;
  policy.entry_points[0].section_index = 0U;
  policy.entry_points[0].offset = 0U;
  memset(&source_analysis, 0, sizeof(source_analysis));
  M68K_C_ASSERT_INT(0, m68k_facts_v2_render_asm_source_analysis_profile_alloc(&object, &policy, &source,
    &profile, &source_analysis, 1U, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(source != NULL);
  M68K_C_ASSERT(strstr(source, "\tadda.w loc_0_00000020(pc,d1.w),a0\n\tjmp (a0)\n") != NULL);
  M68K_C_ASSERT(strstr(source, "loc_0_000001A2:\n\tmoveq.l #64,d0\n\trts\n") != NULL);
  for (code_start_index = 0U; code_start_index < source_analysis.sections[0].code_start_ref_count;
      ++code_start_index) {
    const M68kCodeStartRefIR *ref = &source_analysis.sections[0].code_start_refs[code_start_index];
    if (ref->reason == M68K_FACT_CODE_START_REASON_CONTROL_TARGET && ref->source_offset == 0x0AU &&
        ref->offset == late_target) {
      saw_late_target = 1U;
    }
  }
  M68K_C_ASSERT_U32(1U, saw_late_target);
  for (table_consumer_index = 0U;
       table_consumer_index < source_analysis.sections[0].table_consumer_count;
       ++table_consumer_index) {
    const M68kTableConsumerIR *candidate = &source_analysis.sections[0].table_consumers[table_consumer_index];
    if (candidate->consumer_offset == 0x06U && candidate->table_start_offset == TABLE_OFFSET) {
      table_consumer = candidate;
      break;
    }
  }
  M68K_C_ASSERT(table_consumer != NULL);
  M68K_C_ASSERT_U32(1U, table_consumer->has_index_register);
  M68K_C_ASSERT_U32(M68K_ANALYSIS_REGISTER_DATA, table_consumer->index_register_kind);
  M68K_C_ASSERT_U32(1U, table_consumer->index_register);
  M68K_C_ASSERT_U32(1U, table_consumer->has_target_register);
  M68K_C_ASSERT_U32(M68K_ANALYSIS_REGISTER_ADDRESS, table_consumer->target_register_kind);
  M68K_C_ASSERT_U32(0U, table_consumer->target_register);
  M68K_C_ASSERT_U32(0U, profile.table_target_set_limit_hits);
  M68K_C_ASSERT_U32(0U, profile.asm_source_refused);
  M68K_C_ASSERT_U32(M68K_SOURCE_EXPORT_FAILURE_NONE, profile.asm_source_first_failure_kind);
  m68k_facts_v2_free_text(source);
  m68k_ir_source_analysis_destroy(&source_analysis);
  m68k_object_destroy(&object);
  return 0;
}

static int test_facts_v2_pc_word_dispatch_descriptor_exports_index_domains(void) {
  enum {
    ENTRY_COUNT = 6,
    TABLE_OFFSET = 0x30,
    TARGET_START = TABLE_OFFSET + (ENTRY_COUNT * 2),
    TOTAL_SIZE = TARGET_START + (ENTRY_COUNT * 4)
  };
  M68kObject object;
  M68kSection section;
  M68kObjectAddResult added;
  M68kAnalysisPolicy policy;
  M68kFactsV2Profile profile;
  M68kSourceAnalysisIR source_analysis;
  char *source = NULL;
  const M68kTableConsumerIR *table_consumer = NULL;
  uint32_t table_entry_count = 0U;
  uint32_t saw_last_entry = 0U;
  size_t table_consumer_index;
  size_t table_entry_index;
  uint32_t index;
  uint8_t bytes[TOTAL_SIZE];
  memset(bytes, 0, sizeof(bytes));
  bytes[0x00] = 0x02U;
  bytes[0x01] = 0x41U;
  test_store_u16be(bytes, 0x02U, 0x0007U);
  bytes[0x04] = 0x0CU;
  bytes[0x05] = 0x41U;
  test_store_u16be(bytes, 0x06U, 0x0005U);
  bytes[0x08] = 0x62U;
  bytes[0x09] = 0x0EU;
  bytes[0x0A] = 0xD2U;
  bytes[0x0B] = 0x41U;
  bytes[0x0C] = 0x41U;
  bytes[0x0D] = 0xF9U;
  test_store_u32be(bytes, 0x0EU, TARGET_START);
  bytes[0x12] = 0xD0U;
  bytes[0x13] = 0xFBU;
  bytes[0x14] = 0x10U;
  bytes[0x15] = (uint8_t)(TABLE_OFFSET - 0x14U);
  bytes[0x16] = 0x4EU;
  bytes[0x17] = 0xD0U;
  bytes[0x18] = 0x4EU;
  bytes[0x19] = 0x75U;
  for (index = 0U; index < ENTRY_COUNT; ++index) {
    uint32_t target = TARGET_START + (index * 4U);
    test_store_u16be(bytes, TABLE_OFFSET + (index * 2U), (uint16_t)(target - TARGET_START));
    bytes[target] = 0x70U;
    bytes[target + 1U] = (uint8_t)index;
    bytes[target + 2U] = 0x4EU;
    bytes[target + 3U] = 0x75U;
  }
  memset(&section, 0, sizeof(section));
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  section.kind = M68K_SECTION_CODE;
  section.size = sizeof(bytes);
  section.data_size = sizeof(bytes);
  section.data = bytes;
  added = m68k_object_add_section(&object, &section);
  M68K_C_ASSERT(added.ok);
  memset(&source_analysis, 0, sizeof(source_analysis));
  m68k_analysis_policy_init_default(&policy);
  policy.entry_point_count = 1U;
  policy.entry_points[0].has_section_index = 1U;
  policy.entry_points[0].section_index = 0U;
  policy.entry_points[0].offset = 0U;
  M68K_C_ASSERT_INT(0, m68k_facts_v2_render_asm_source_analysis_profile_alloc(&object, &policy, &source,
    &profile, &source_analysis, 1U, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(source != NULL);
  for (table_consumer_index = 0U;
       table_consumer_index < source_analysis.sections[0].table_consumer_count;
       ++table_consumer_index) {
    const M68kTableConsumerIR *candidate = &source_analysis.sections[0].table_consumers[table_consumer_index];
    if (candidate->consumer_offset == 0x12U &&
        candidate->table_start_offset == TABLE_OFFSET &&
        candidate->table_kind_id == M68K_ANALYSIS_TABLE_KIND_RELATIVE_CODE_DISPATCH &&
        candidate->source_pattern_id == M68K_ANALYSIS_STRUCTURED_DATA_SOURCE_PATTERN_INDEXED_WORD_DISPATCH) {
      table_consumer = candidate;
      break;
    }
  }
  M68K_C_ASSERT(table_consumer != NULL);
  M68K_C_ASSERT_U32(1U, table_consumer->has_index_register);
  M68K_C_ASSERT_U32(M68K_ANALYSIS_REGISTER_DATA, table_consumer->index_register_kind);
  M68K_C_ASSERT_U32(1U, table_consumer->index_register);
  M68K_C_ASSERT_U32(M68K_ANALYSIS_TABLE_ENTRY_COUNT_PROOF_INDEX_COMPARE_DOMAIN,
    table_consumer->entry_count_proof_id);
  M68K_C_ASSERT_U32(M68K_ANALYSIS_TABLE_STOP_REASON_INDEX_COMPARE_BRANCH_BOUND,
    table_consumer->table_stop_reason_id);
  M68K_C_ASSERT_U32(1U, table_consumer->has_index_mask_domain);
  M68K_C_ASSERT_U32(0U, table_consumer->index_mask_min);
  M68K_C_ASSERT_U32(7U, table_consumer->index_mask_max);
  M68K_C_ASSERT_U32(1U, table_consumer->has_index_compare_domain);
  M68K_C_ASSERT_U32(0U, table_consumer->index_compare_min);
  M68K_C_ASSERT_U32(5U, table_consumer->index_compare_max);
  M68K_C_ASSERT_U32(M68K_ASM_MNEMONIC_BHI, table_consumer->index_domain_branch_mnemonic_id);
  for (table_entry_index = 0U;
       table_entry_index < source_analysis.sections[0].table_entry_count;
       ++table_entry_index) {
    const M68kTableEntryIR *entry = &source_analysis.sections[0].table_entries[table_entry_index];
    if (entry->table_start_offset != TABLE_OFFSET ||
        entry->table_kind_id != M68K_ANALYSIS_TABLE_KIND_RELATIVE_CODE_DISPATCH) {
      continue;
    }
    ++table_entry_count;
    M68K_C_ASSERT_U32(2U, entry->entry_size);
    M68K_C_ASSERT_U32(2U, entry->raw_value_width);
    M68K_C_ASSERT_U32(M68K_TABLE_ENTRY_TARGET_STATUS_ACCEPTED_TARGET, entry->target_status);
    M68K_C_ASSERT_U32(M68K_ANALYSIS_CONFLICT_STATE_CLEAN, entry->conflict_state);
    if (entry->entry_index == 5U && entry->target_offset == TARGET_START + (5U * 4U)) saw_last_entry = 1U;
  }
  M68K_C_ASSERT_U32(ENTRY_COUNT, table_entry_count);
  M68K_C_ASSERT_U32(1U, saw_last_entry);
  M68K_C_ASSERT_U32(0U, profile.asm_source_refused);
  M68K_C_ASSERT_U32(M68K_SOURCE_EXPORT_FAILURE_NONE, profile.asm_source_first_failure_kind);
  m68k_facts_v2_free_text(source);
  m68k_ir_source_analysis_destroy(&source_analysis);
  m68k_object_destroy(&object);
  return 0;
}

