  M68K_C_ASSERT(strstr(preview.asm_source_text, "    ORG $4\n") == NULL);
  M68K_C_ASSERT(strstr(preview.asm_source_text, "\tdc.b $00,$01,$02,$03\n") != NULL);
  M68K_C_ASSERT_U32(0U, preview.asm_source_instruction_render_failures);
