  m68k_ir_statement_init(&data_stmt);
  data_stmt.kind = M68K_STATEMENT_DATA;
  data_stmt.offset = 2U;
  data_stmt.u.data.kind = M68K_DATA_ITEM_BYTES;
  data_stmt.u.data.data = data_bytes;
