static int test_render_plan_marks_emitted_org_subline_as_directive(void) {
  M68kObject object;
  M68kSection section;
  M68kObjectAddResult added;
  M68kDecodeIR decode;
  M68kFactIR facts;
  M68kRenderIRPreview preview;
  M68kFact fact;
  M68kAnalysisLabelPoint analysis_labels[2];
  size_t analysis_label_count = 0U;
  uint8_t *accepted_start[1];
  uint8_t *accepted_bytes[1];
  uint8_t start_map[24];
  uint8_t byte_map[24];
  const M68kRenderPlanRow *org_row = NULL;
  size_t row_index;
  uint8_t bytes[20] = {
    0x4eu, 0xf9u, 0x00u, 0x00u, 0x00u, 0x80u,
    0x00u, 0x00u, 0x00u, 0x00u, 0x00u, 0x00u, 0x00u, 0x00u, 0x00u, 0x00u,
    0x4eu, 0x71u, 0x4eu, 0x75u
  };
  memset(&section, 0, sizeof(section));
  memset(start_map, 0, sizeof(start_map));
  memset(byte_map, 0, sizeof(byte_map));
  accepted_start[0] = start_map;
  accepted_bytes[0] = byte_map;
  start_map[0] = 1U;
  memset(&byte_map[0], 1, 6U);
  start_map[0x10] = 1U;
  memset(&byte_map[0x10], 1, 4U);
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  section.kind = M68K_SECTION_CODE;
  section.size = sizeof(bytes);
  section.data_size = sizeof(bytes);
  section.data = bytes;
  added = m68k_object_add_section(&object, &section);
  M68K_C_ASSERT(added.ok);
  m68k_decode_ir_init(&decode);
  m68k_fact_ir_init(&facts);
  m68k_render_ir_preview_init(&preview);
  M68K_C_ASSERT_INT(0, m68k_decode_ir_build_object(&decode, &object, M68K_ASM_CPU_68060,
    m68k_diag_sink(NULL)));
  M68K_C_ASSERT_INT(0, test_append_analysis_label(analysis_labels, &analysis_label_count,
    sizeof(analysis_labels) / sizeof(analysis_labels[0]), 0U, 0U, M68K_FACT_CONFIDENCE_TOOL_INFERRED));
  M68K_C_ASSERT_INT(0, test_append_analysis_label(analysis_labels, &analysis_label_count,
    sizeof(analysis_labels) / sizeof(analysis_labels[0]), 0U, 0x10U, M68K_FACT_CONFIDENCE_TOOL_INFERRED));
  memset(&fact, 0, sizeof(fact));
  fact.kind = M68K_FACT_CODE_START;
  fact.confidence = M68K_FACT_CONFIDENCE_TOOL_INFERRED;
  fact.section_index = 0U;
  fact.offset = 0x10U;
  fact.reason = M68K_FACT_CODE_START_REASON_CONTROL_TARGET;
  fact.has_runtime_address = 1U;
  fact.runtime_address = 0x80U;
  M68K_C_ASSERT_INT(0, m68k_fact_ir_append(&facts, &fact));
  memset(&fact, 0, sizeof(fact));
  fact.kind = M68K_FACT_RUNTIME_ADDRESS_RANGE;
  fact.confidence = M68K_FACT_CONFIDENCE_TOOL_INFERRED;
  fact.section_index = 0U;
  fact.offset = 0x10U;
  fact.has_runtime_address = 1U;
  fact.runtime_kind = M68K_FACT_RUNTIME_RANGE_KIND_DISCOVERED_COPY;
  fact.runtime_address = 0x80U;
  fact.size = 4U;
  M68K_C_ASSERT_INT(0, m68k_fact_ir_append(&facts, &fact));
  memset(&fact, 0, sizeof(fact));
  fact.kind = M68K_FACT_RUNTIME_ADDRESS_REF;
  fact.confidence = M68K_FACT_CONFIDENCE_TOOL_INFERRED;
  fact.section_index = 0U;
  fact.offset = 0U;
  fact.target_section_index = 0U;
  fact.target_offset = 0x10U;
  fact.has_runtime_address = 1U;
  fact.runtime_address = 0x80U;
  M68K_C_ASSERT_INT(0, m68k_fact_ir_append(&facts, &fact));
  M68K_C_ASSERT_INT(0, test_render_ir_preview_build(&object, &decode, &facts, NULL,
    accepted_start, accepted_bytes, analysis_labels, analysis_label_count, 0, 1, 1, 1, &preview));
  for (row_index = 0U; row_index < preview.asm_source_plan.row_count; ++row_index) {
    const M68kRenderPlanRow *row = &preview.asm_source_plan.rows[row_index];
    if (row->text != NULL && strstr(row->text, "    ORG $80\n") != NULL) {
      org_row = row;
      break;
    }
  }
  M68K_C_ASSERT(org_row != NULL);
  M68K_C_ASSERT(strstr(org_row->text, "loc_0_00000010:\n    ORG $80\nabs_0_00000080:\n") != NULL);
  M68K_C_ASSERT_U32(2U, org_row->directive_line_mask);
  M68K_C_ASSERT_U32(M68K_RENDER_PLAN_ROW_LABEL, org_row->kind);
  M68K_C_ASSERT_U32(0U, preview.asm_source_instruction_render_failures);
  m68k_render_ir_preview_destroy(&preview);
  m68k_fact_ir_destroy(&facts);
  m68k_decode_ir_destroy(&decode);
  m68k_object_destroy(&object);
  return 0;
}

static int test_facts_v2_render_asm_source_splits_raw_data_plan_rows(void) {
  M68kObject object;
  M68kSection section;
  M68kObjectAddResult added;
  M68kDecodeIR decode;
  M68kFactIR facts;
  M68kAnalysisPolicy policy;
  M68kRenderIRPreview preview;
  uint8_t *accepted_start[1];
  uint8_t *accepted_bytes[1];
  uint8_t start_map[40];
  uint8_t byte_map[40];
  uint8_t bytes[40];
  size_t index;
  size_t data_row_count = 0U;
  const M68kRenderPlanRow *mid_row;
  const uint32_t expected_offsets[3] = {0U, 16U, 24U};
  const uint32_t expected_sizes[3] = {16U, 8U, 16U};

  memset(&section, 0, sizeof(section));
  memset(start_map, 0, sizeof(start_map));
  memset(byte_map, 0, sizeof(byte_map));
  for (index = 0U; index < sizeof(bytes); ++index) bytes[index] = (uint8_t)(index + 1U);
  accepted_start[0] = start_map;
  accepted_bytes[0] = byte_map;
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  m68k_analysis_policy_init_default(&policy);
  policy.named_label_count = 1U;
  policy.named_labels[0].has_section_index = 1U;
  policy.named_labels[0].section_index = 0U;
  policy.named_labels[0].domain = M68K_ANALYSIS_LABEL_DOMAIN_SOURCE;
  policy.named_labels[0].offset = 24U;
  snprintf(policy.named_labels[0].name, sizeof(policy.named_labels[0].name), "data_midpoint");
  section.kind = M68K_SECTION_DATA;
  section.size = sizeof(bytes);
  section.data_size = sizeof(bytes);
  section.data = bytes;
  added = m68k_object_add_section(&object, &section);
  M68K_C_ASSERT(added.ok);
  m68k_decode_ir_init(&decode);
  m68k_fact_ir_init(&facts);
  m68k_render_ir_preview_init(&preview);

  M68K_C_ASSERT_INT(0, m68k_decode_ir_build_object(&decode, &object, M68K_ASM_CPU_68060,
    m68k_diag_sink(NULL)));
  M68K_C_ASSERT_INT(0, test_render_ir_preview_build(&object, &decode, &facts, &policy,
    accepted_start, accepted_bytes, NULL, 0U, 0, 1, 1, 1, &preview));
  for (index = 0U; index < preview.asm_source_plan.row_count; ++index) {
    const M68kRenderPlanRow *row = &preview.asm_source_plan.rows[index];
    if (row->kind != M68K_RENDER_PLAN_ROW_DATA) continue;
    M68K_C_ASSERT(data_row_count < 3U);
    M68K_C_ASSERT_U32(expected_offsets[data_row_count], row->source_offset);
    M68K_C_ASSERT_U32(expected_sizes[data_row_count], row->source_size);
    M68K_C_ASSERT_U32(1U, row->line_count);
    data_row_count++;
  }
  M68K_C_ASSERT_U32(3U, (uint32_t)data_row_count);
  mid_row = m68k_render_plan_find_row_for_source_offset(&preview.asm_source_plan, 0U, 24U);
  M68K_C_ASSERT(mid_row != NULL);
  M68K_C_ASSERT_U32(M68K_RENDER_PLAN_ROW_DATA, mid_row->kind);
  M68K_C_ASSERT_U32(24U, mid_row->source_offset);
  M68K_C_ASSERT_U32(16U, mid_row->source_size);
  M68K_C_ASSERT(strstr(preview.asm_source_text, "data_midpoint:\n\tdc.b $19,$1A,$1B,$1C") != NULL);

  m68k_render_ir_preview_destroy(&preview);
  m68k_fact_ir_destroy(&facts);
  m68k_decode_ir_destroy(&decode);
  m68k_analysis_policy_destroy(&policy);
  m68k_object_destroy(&object);
  return 0;
}

