  M68K_C_ASSERT(strstr(source, "copper_list:\n") != NULL);
  M68K_C_ASSERT(strstr(source,
    "\tdc.w diwstrt,$2C81\t; display window start v=$2C h=$81\n") != NULL);
  M68K_C_ASSERT(strstr(source,
    "\tdc.w diwstop,$2CC1\t; display window stop v=$2C h=$C1\n") != NULL);
