  M68K_C_ASSERT(strstr(analysis_json, "\"note_text\":\"sprite pointer 0 disabled\"") != NULL);
  M68K_C_ASSERT(strstr(analysis_json, "\"note_text\":\"copper wait v=$2C h=$06 mask $FFFE\"") != NULL);
