static int test_facts_v2_copper_bitmap_pointers_render_display_layout_comment(void) {
  M68kObject object;
  M68kSection section;
  M68kObjectAddResult added;
  M68kAnalysisPolicy policy;
  M68kFactsV2Profile profile;
  M68kSourceAnalysisIR source_analysis;
  char *source = NULL;
  char *analysis_json = NULL;
  const M68kRuntimeAddressRefIR *first_bitmap = NULL;
  const M68kRuntimeAddressRefIR *second_bitmap = NULL;
  int found_expected_first_hi = 0;
  int found_expected_first_lo = 0;
  int found_expected_second_hi = 0;
  int found_expected_second_lo = 0;
  int found_semantic_first_hi = 0;
  int found_semantic_first_lo = 0;
  int found_semantic_second_hi = 0;
  int found_semantic_second_lo = 0;
  size_t index;
  uint8_t bytes[32] = {
    0x23u, 0xFCu, 0x00u, 0x00u, 0x00u, 0x0Cu, 0x00u, 0xDFu, 0xF0u, 0x80u,
    0x4Eu, 0x75u,
    0x00u, 0xE0u, 0x00u, 0x01u,
    0x00u, 0xE2u, 0x00u, 0x00u,
    0x00u, 0xE4u, 0x00u, 0x01u,
    0x00u, 0xE6u, 0x20u, 0x00u,
    0xFFu, 0xFFu, 0xFFu, 0xFEu
  };
  memset(&section, 0, sizeof(section));
  M68K_C_ASSERT_INT(0, m68k_object_create(&object));
  object.platform_backend_kind = M68K_PLATFORM_BACKEND_AMIGA_HUNK;
  section.kind = M68K_SECTION_CODE;
  section.size = sizeof(bytes);
  section.data_size = sizeof(bytes);
  section.data = bytes;
  added = m68k_object_add_section(&object, &section);
  M68K_C_ASSERT(added.ok);
  m68k_analysis_policy_init_default(&policy);
  policy.runtime_range_count = 1U;
  policy.runtime_ranges[0].has_section_index = 1U;
  policy.runtime_ranges[0].section_index = 0U;
  policy.runtime_ranges[0].offset = 0U;
  policy.runtime_ranges[0].size = (uint32_t)sizeof(bytes);
  policy.runtime_ranges[0].runtime_address = 0U;
  M68K_C_ASSERT_INT(0, m68k_facts_v2_render_asm_source_analysis_profile_alloc(&object, &policy, &source,
    &profile, &source_analysis, 1U, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(source != NULL);
  M68K_C_ASSERT(strstr(source, "bitmap_00010000\tEQU\t$10000\n") != NULL);
  M68K_C_ASSERT(strstr(source, "bitmap_00012000\tEQU\t$12000\n") != NULL);
  M68K_C_ASSERT(strstr(source,
    "loc_0_0000000C:\n"
    "    ; display layout 2 bitmap planes $00010000..$00012000 step $2000\n"
    "\tdc.w bplpt,bitmap_00010000_hi\t; bitmap pointer $00010000\n"
    "\tdc.w bplpt+$02,bitmap_00010000_lo\n"
    "\tdc.w bplpt+$04,bitmap_00012000_hi\t; bitmap pointer $00012000\n"
    "\tdc.w bplpt+$06,bitmap_00012000_lo\n") != NULL);
  for (index = 0U; index < source_analysis.sections[0].runtime_address_ref_count; ++index) {
    const M68kRuntimeAddressRefIR *ref = &source_analysis.sections[0].runtime_address_refs[index];
    if (!runtime_address_ref_has_data_class(ref, M68K_ANALYSIS_STRUCTURED_DATA_ROLE_BITMAP)) continue;
    if (ref->offset == 0x0CU) first_bitmap = ref;
    if (ref->offset == 0x14U) second_bitmap = ref;
  }
  M68K_C_ASSERT(first_bitmap != NULL);
  M68K_C_ASSERT_U32(0x10000U, first_bitmap->runtime_address);
  M68K_C_ASSERT_U32(0x2000U, first_bitmap->size);
  M68K_C_ASSERT_U32(0U, first_bitmap->has_target);
  M68K_C_ASSERT(second_bitmap != NULL);
  M68K_C_ASSERT_U32(0x12000U, second_bitmap->runtime_address);
  M68K_C_ASSERT_U32(0x2000U, second_bitmap->size);
  M68K_C_ASSERT_U32(0U, second_bitmap->has_target);
  for (index = 0U; index < source_analysis.sections[0].expected_symbol_access_count; ++index) {
    const M68kExpectedSymbolAccessIR *expected = &source_analysis.sections[0].expected_symbol_accesses[index];
    if (expected->producer == NULL || strcmp(expected->producer, "copper_runtime_pointer_word_symbol") != 0 ||
        expected->symbol_name == NULL ||
        expected->access_kind != M68K_EXPECTED_SYMBOL_ACCESS_EQUATE ||
        expected->operand_index != UINT32_MAX) {
      continue;
    }
    if (expected->offset == 0x0CU && strcmp(expected->symbol_name, "bitmap_00010000_hi") == 0)
      found_expected_first_hi = 1;
    if (expected->offset == 0x10U && strcmp(expected->symbol_name, "bitmap_00010000_lo") == 0)
      found_expected_first_lo = 1;
    if (expected->offset == 0x14U && strcmp(expected->symbol_name, "bitmap_00012000_hi") == 0)
      found_expected_second_hi = 1;
    if (expected->offset == 0x18U && strcmp(expected->symbol_name, "bitmap_00012000_lo") == 0)
      found_expected_second_lo = 1;
  }
  M68K_C_ASSERT(found_expected_first_hi);
  M68K_C_ASSERT(found_expected_first_lo);
  M68K_C_ASSERT(found_expected_second_hi);
  M68K_C_ASSERT(found_expected_second_lo);
  for (index = 0U; index < source_analysis.sections[0].platform_semantic_use_count; ++index) {
    const M68kPlatformSemanticUseIR *use = &source_analysis.sections[0].platform_semantic_uses[index];
    if (use->kind != M68K_PLATFORM_SEMANTIC_USE_COPPER_ROW || !use->has_operand_expr ||
        use->operand_expr == NULL ||
        (use->role_flags & M68K_ANALYSIS_STRUCTURED_DATA_ROLE_BITMAP) == 0U ||
        !use->has_runtime_address) {
      continue;
    }
    if (use->offset == 0x0CU && use->runtime_address == 0x10000U &&
        strcmp(use->operand_expr, "bitmap_00010000_hi") == 0)
      found_semantic_first_hi = 1;
    if (use->offset == 0x10U && use->runtime_address == 0x10000U &&
        strcmp(use->operand_expr, "bitmap_00010000_lo") == 0)
      found_semantic_first_lo = 1;
    if (use->offset == 0x14U && use->runtime_address == 0x12000U &&
        strcmp(use->operand_expr, "bitmap_00012000_hi") == 0)
      found_semantic_second_hi = 1;
    if (use->offset == 0x18U && use->runtime_address == 0x12000U &&
        strcmp(use->operand_expr, "bitmap_00012000_lo") == 0)
      found_semantic_second_lo = 1;
  }
  M68K_C_ASSERT(found_semantic_first_hi);
  M68K_C_ASSERT(found_semantic_first_lo);
  M68K_C_ASSERT(found_semantic_second_hi);
  M68K_C_ASSERT(found_semantic_second_lo);
  M68K_C_ASSERT_INT(0, source_analysis_to_json(&source_analysis, &analysis_json, m68k_diag_sink(NULL)));
  M68K_C_ASSERT(analysis_json != NULL);
  M68K_C_ASSERT(strstr(analysis_json, "\"kind_name\":\"copper_display_layout\"") != NULL);
  M68K_C_ASSERT(strstr(analysis_json,
    "\"note_text\":\"display layout 2 bitmap planes $00010000..$00012000 step $2000\"") != NULL);
  M68K_C_ASSERT(strstr(analysis_json, "\"operand_expr\":\"bitmap_00010000_hi\"") != NULL);
  M68K_C_ASSERT(strstr(analysis_json, "\"operand_expr\":\"bitmap_00012000_lo\"") != NULL);
  M68K_C_ASSERT_U32(0U, profile.asm_source_refused);
  M68K_C_ASSERT_U32(0U, profile.asm_source_instruction_byte_mismatches);
  free(analysis_json);
  m68k_facts_v2_free_text(source);
  m68k_ir_source_analysis_destroy(&source_analysis);
  m68k_object_destroy(&object);
  return 0;
}

